pub enum List<T> {
    Cons(T, Box<List<T>>),
    Nil,
}

pub fn nth_shared<T>(mut ls: &List<T>, mut i: u32) -> Option<&T> {
    while let List::Cons(x, tl) = ls {
        if i == 0 {
            return Some(x);
        } else {
            ls = tl;
            i -= 1;
        }
    }
    None
}

pub fn nth_mut<T>(mut ls: &mut List<T>, mut i: u32) -> Option<&mut T> {
    while let List::Cons(x, tl) = ls {
        if i == 0 {
            return Some(x);
        } else {
            ls = tl;
            i -= 1;
        }
    }
    None
}

